css:
.d-ce{width:100%;max-width:340px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden}
.d-ce-tabs{display:flex;gap:2px;padding:6px 8px;border-bottom:1px solid var(--line)}
.d-ce-tabs button{padding:4px 10px;border:1px solid transparent;border-radius:999px;background:transparent;color:var(--muted);font:inherit;font-size:11px;cursor:pointer}
.d-ce-tabs button[aria-selected="true"]{border-color:var(--line);background:var(--bg);color:var(--ink)}
.d-ce-body{display:grid;place-items:center;height:140px;padding:14px;text-align:center}
.d-ce-t{font-size:11px;color:var(--ink);margin:0 0 2px}
.d-ce-p{font-size:11px;color:var(--muted);margin:0;max-width:26ch}
.d-ce-btn{margin-top:10px;padding:5px 14px;border:1px solid var(--line);border-radius:999px;background:var(--bg);color:var(--ink);font:inherit;font-size:11px;cursor:pointer}
.d-ce-sk{width:100%;height:96px;display:flex;align-items:flex-end;gap:6px}
.d-ce-sk i{flex:1;border-radius:2px 2px 0 0;background:color-mix(in srgb,var(--ink) 10%,var(--paper));animation:d-chart-empty-states-pulse 900ms var(--ease-print) infinite alternate}
.d-ce-sk i:nth-child(2n){animation-delay:120ms}
@keyframes d-chart-empty-states-pulse{from{opacity:.55}to{opacity:1}}

init:
root => {
  const body = root.querySelector('[data-body]');
  const tabs = [...root.querySelectorAll('[data-s]')];
  if (!body || !tabs.length) return;
  const line = (cls, text) => { const el = document.createElement('p'); el.className = cls; el.textContent = text; return el; };
  const box = (title, note, retry) => {
    const wrap = document.createElement('div');
    wrap.appendChild(line('d-ce-t', title));
    wrap.appendChild(line('d-ce-p', note));
    if (retry) { const b = document.createElement('button'); b.type = 'button'; b.className = 'd-ce-btn'; b.textContent = '重试'; wrap.appendChild(b); }
    return wrap;
  };
  const render = k => {
    body.textContent = '';
    if (k === 'loading') {
      const sk = document.createElement('div');
      sk.className = 'd-ce-sk';
      [38, 64, 47, 82, 56, 71].forEach(h => { const i = document.createElement('i'); i.style.height = h + '%'; sk.appendChild(i); });
      body.appendChild(sk);
    } else if (k === 'error') {
      body.appendChild(box('取数没成功', '接口 8 秒没回应，已停止等待。', true));
    } else {
      body.appendChild(box('这段时间没有记录', '换个时间范围，或者等明天第一批数据进来。', false));
    }
    tabs.forEach(t => t.setAttribute('aria-selected', t.dataset.s === k ? 'true' : 'false'));
  };
  tabs.forEach(t => { t.onclick = () => render(t.dataset.s); });
  render('empty');
}
